const result = $input.first()?.json ?? {};
const code = Number(result.code);
if (code !== 0) {
  const match = String(result.stderr ?? '').match(/RD_BOM_SYNC_FAILED:[A-Z0-9_]+/);
  throw new Error(match?.[0] ?? `RD_BOM_SYNC_COMMAND_EXIT_${Number.isFinite(code) ? code : 'UNKNOWN'}`);
}
const lines = String(result.stdout ?? '').split(/\r?\n/).map(line => line.trim()).filter(Boolean);
const jsonLine = [...lines].reverse().find(line => line.startsWith('{') && line.endsWith('}'));
if (!jsonLine) throw new Error('RD_BOM_SYNC_RESULT_MISSING');
let summary;
try { summary = JSON.parse(jsonLine); } catch { throw new Error('RD_BOM_SYNC_RESULT_INVALID'); }
if (summary.status !== 'SUCCESS' || summary.mode !== 'INCREMENTAL') throw new Error('RD_BOM_SYNC_RESULT_NOT_SUCCESS');
return [{ json: summary }];

const result = $input.first()?.json ?? {};
const code = Number(result.code);
if (code !== 0) {
  const match = String(result.stderr ?? '').match(/RD_BOM_[A-Z0-9_]+/);
  throw new Error(match?.[0] ?? `RD_BOM_HEALTH_COMMAND_EXIT_${Number.isFinite(code) ? code : 'UNKNOWN'}`);
}
const lines = String(result.stdout ?? '').split(/\r?\n/).map(line => line.trim()).filter(Boolean);
const jsonLine = [...lines].reverse().find(line => line.startsWith('{') && line.endsWith('}'));
if (!jsonLine) throw new Error('RD_BOM_HEALTH_RESULT_MISSING');
let status;
try { status = JSON.parse(jsonLine); } catch { throw new Error('RD_BOM_HEALTH_RESULT_INVALID'); }
if (status.status !== 'SUCCESS' || (status.alertLevel && status.alertEnqueueOk !== true)) throw new Error('RD_BOM_HEALTH_ALERT_NOT_QUEUED');
return [{ json: status }];
